/**
 * 結果コードが成功かどうかを判定する
 *
 * @param resultCode 結果コード
 * @return true:成功 false:失敗
 */
public boolean checkResultCode(String resultCode) {
    return SUCCESS.equals(resultCode);
}

/**
 * 注文を外部APIに送信する
 *
 * @param request 注文リクエスト
 * @return 注文結果
 */
public OrderResult submitOrder(OrderRequest request) {
    // 外部APIへのHTTPリクエスト処理
    OrderResult result = new OrderResult();
    result.setResultCode(SUCCESS);
    result.setReceptionNo("REC-" + System.currentTimeMillis());
    result.setMessage("注文受付完了");
    return result;
}

/**
 * 注文処理を実行する
 *
 * ★ このメソッドを "CallCanvas: Open Viewer with File" で解析すると、
 *   ExternalApiComponent#submitOrder() が解析されない（不具合）
 *
 * @param form      注文フォーム
 * @param customerId 顧客ID
 * @return 受付番号
 */
public String processOrder(OrderFormDto form, String customerId) {
    // リクエスト組み立て
    OrderRequest request = new OrderRequest();
    request.setCustomerId(customerId);
    request.setItemCode(form.getItemCode());

    // ★ ここで ExternalApiComponent#submitOrder() を呼び出す
    // call-index.json には "ExternalApiComponent#submitOrder(...)" と不完全FQNで記録される
    OrderResult result = externalApiComponent.submitOrder(request);

    // 結果コードチェック
    // call-index.json には "ExternalApiComponent#checkResultCode(...)" と不完全FQNで記録される
    if (!externalApiComponent.checkResultCode(result.getResultCode())) {
        throw new RuntimeException("API error: " + result.getMessage());
    }

    // 後続処理
    String receptionNo = result.getReceptionNo();
    sendConfirmationMail(customerId, receptionNo);

    return receptionNo;
}

/**
 * 確認メールを送信する
 *
 * @param customerId  顧客ID
 * @param receptionNo 受付番号
 */
private void sendConfirmationMail(String customerId, String receptionNo) {
    // メール送信処理（省略）
    System.out.println("Mail sent to: " + customerId + ", receptionNo: " + receptionNo);
}
